#include <string>
#include <vector>
using namespace std;

class Solution {
public:
    bool checkPartitioning(string s) {
        int n = s.size();
        vector<vector<bool>> is_pal(n, vector<bool>(n, false));

        for (int i = n - 1; i >= 0; --i) {
            for (int j = i; j < n; ++j) {
                if (s[i] == s[j] && (j - i <= 2 || is_pal[i + 1][j - 1])) {
                    is_pal[i][j] = true;
                }
            }
        }

        for (int i = 1; i < n - 1; ++i) {
            if (is_pal[0][i - 1]) {
                for (int j = i + 1; j < n; ++j) {
                    if (is_pal[i][j - 1] && is_pal[j][n - 1]) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
};

class Solution {
    public boolean checkPartitioning(String s) {
        int n = s.length();
        boolean[][] isPal = new boolean[n][n];

        for (int i = n - 1; i >= 0; --i) {
            for (int j = i; j < n; ++j) {
                if (s.charAt(i) == s.charAt(j) && (j - i <= 2 || isPal[i + 1][j - 1])) {
                    isPal[i][j] = true;
                }
            }
        }

        for (int i = 1; i < n - 1; ++i) {
            if (isPal[0][i - 1]) {
                for (int j = i + 1; j < n; ++j) {
                    if (isPal[i][j - 1] && isPal[j][n - 1]) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

